h1 = document.querySelector('h1');

function changeColor(color, delay) {
    return new Promise((resolve, reject) => {

        setTimeout(() => {
            h1.style.color = color;
            resolve(`${color} color changed`);
        }, delay);

    });
}

let p1 = changeColor("red", 1000);

console.log("p1:", p1);   // pending

p1.then(() => {
    console.log("p1:", p1);   // fulfilled
    console.log("red color was completed");

    let p2 = changeColor("green", 5000);

    console.log("p2:", p2);   // pending

    p2.then(() => {
        console.log("p2:", p2);   // fulfilled
        console.log("green color was completed");

        let p3 = changeColor("blue", 1000);

        console.log("p3:", p3);   // pending

        p3.then(() => {
            console.log("p3:", p3);   // fulfilled
            console.log("blue color was completed");
        });
    });
});

/*
Promise.all()

Suppose the requirement is:

"Save KMIT, CSE and Vishal. I want to continue only when ALL three database operations succeed."
*/

function saveToDb(data) {
    return new Promise((resolve, reject) => {

        let internetSpeed = Math.floor(Math.random() * 10) + 1;

        if (internetSpeed > 4) {
            resolve(`${data} : data was saved`);
        } else {
            reject(`${data} : failure - weak connection`);
        }

    });
}

let p1 = saveToDb("kmit");
let p2 = saveToDb("cse");
let p3 = saveToDb("vishal");

Promise.all([p1, p2, p3])
    .then((results) => {
        console.log("ALL DATA SAVED");
        console.log(results);
    })
    .catch((error) => {
        console.error("At least one save failed:", error);
    });
